.btn--light {
  color: var(--color-dark);
  background-color: var(--color-light);
}

.pagination {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: var(--space-xxs);
  padding: var(--space-m) 0;
  list-style: none;
}

.pagination a,
.pagination span {
  display: inline-block;
  padding: var(--space-xxs) var(--space-s);
  border-radius: var(--border-radius);
  font-weight: bold;
  text-decoration: none;
  transition: filter 200ms;
}

.pagination a {
  color: var(--color-white);
  background-image: linear-gradient(to right, var(--color-secondary), var(--color-secondary-rotate));
}

.pagination a:hover,
.pagination a:focus,
.pagination a:active {
  filter: saturate(1.2) brightness(110%);
}

.pagination .current {
  color: var(--color-dark);
  background-color: var(--color-light);
}

.pagination .disabled {
  color: var(--color-text-muted);
  background-color: transparent;
  cursor: default;
  filter: none;
}

scope :ordered, -> { order({:id => :desc}) }
scope :failed, -> { where({:status => Status::FAILED}) }
scope :search_by_title, ->(q) { where("title ILIKE ?", "%#{q}%") if q.present? }

